declare(strict_types=1);ini_set('display_errors','0');error_reporting(E_ALL);session_start();require_once __DIR__.'/../config/db.php';header('Content-Type: application/json; charset=utf-8');function respond(array$d,int$s=200):never{http_response_code($s);echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);exit;}try{if(empty($_SESSION['user_id']))respond(['success'=>false,'error'=>'Nicht angemeldet.'],401);if($_SERVER['REQUEST_METHOD']!=='POST')respond(['success'=>false,'error'=>'Methode nicht erlaubt.'],405);$x=json_decode(file_get_contents('php://input'),true);if(!is_array($x))respond(['success'=>false,'error'=>'Ungültiges JSON.'],400);$id=trim((string)($x['id']??''));$key=trim((string)($x['confirmation_key']??''));$pdo->beginTransaction();$q=$pdo->prepare('SELECT id,project_id,requirement_key FROM requirement_documents WHERE id=? FOR UPDATE');$q->execute([$id]);$d=$q->fetch(PDO::FETCH_ASSOC);if(!$d){$pdo->rollBack();respond(['success'=>false,'error'=>'Dokument nicht gefunden.'],404);}if(!hash_equals((string)$d['requirement_key'],$key)){$pdo->rollBack();respond(['success'=>false,'error'=>'Bestätigungskennung stimmt nicht überein.'],409);}$f=$pdo->prepare('SELECT relative_path FROM requirement_document_files WHERE document_id=?');$f->execute([$id]);$paths=$f->fetchAll(PDO::FETCH_COLUMN);$pdo->prepare('DELETE FROM requirement_documents WHERE id=?')->execute([$id]);$pdo->commit();$base=realpath(__DIR__.'/../uploads/documents');$count=0;if($base)foreach($paths as$rel){$path=realpath(__DIR__.'/../'.ltrim((string)$rel,'/\\'));if($path&&str_starts_with($path,$base.DIRECTORY_SEPARATOR)&&is_file($path)&&@unlink($path))$count++;}respond(['success'=>true,'deleted_id'=>$id,'deleted_files'=>$count]);}catch(Throwable$e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();respond(['success'=>false,'error'=>$e->getMessage()],500);}
